/* ============================================================
   Foundry integration -- Target acquisition
   ============================================================ */

/**
 * Return the current user's Foundry token targets as Token objects.
 *
 * This is selection state only. Target legality belongs to the
 * Targeting / Spatial domain and action-specific rules.
 */
function getFrameConnUserTargets() {
  return Array.from(
    game?.user?.targets ??
    []
  );
}


/**
 * Activate Foundry's Token layer with its built-in target tool.
 *
 * Foundry v13 exposes TokenLayer.activate({ tool: "target" }); this
 * keeps Frame Conn on the native target-selection interaction rather
 * than inventing a parallel canvas click mode.
 */
function activateFrameConnTargetTool() {
  const tokenLayer =
    canvas?.tokens ??
    null;

  if (
    !tokenLayer ||
    typeof tokenLayer.activate !==
      "function"
  ) {
    throw new Error(
      "Frame Conn could not activate Foundry's Token target tool."
    );
  }

  tokenLayer.activate({
    tool:
      "target"
  });

  return true;
}


/**
 * Wait for the current user to acquire a Foundry token target.
 *
 * Existing targets win immediately. When no target exists, this
 * switches Foundry to the native target tool and resolves on the next
 * targetToken hook for the current user. Escape cancels the prompt.
 */
async function promptFrameConnForTarget() {
  const existingTargets =
    getFrameConnUserTargets();

  if (
    existingTargets.length > 0
  ) {
    return existingTargets;
  }

  activateFrameConnTargetTool();

  ui.notifications.info(
    "Select a target for this action. Press Escape to cancel."
  );

  return new Promise(
    resolve => {
      let settled =
        false;

      let targetHookId =
        null;

      const cleanup =
        () => {
          if (
            targetHookId != null
          ) {
            Hooks.off(
              "targetToken",
              targetHookId
            );
          }

          window.removeEventListener(
            "keydown",
            handleKeyDown,
            true
          );
        };

      const finish =
        value => {
          if (settled) {
            return;
          }

          settled =
            true;

          cleanup();
          resolve(value);
        };

      const handleKeyDown =
        event => {
          if (
            event.key ===
              "Escape"
          ) {
            finish(null);
          }
        };

      targetHookId =
        Hooks.on(
          "targetToken",
          (
            user,
            token,
            targeted
          ) => {
            if (
              user?.id !==
                game?.user?.id ||
              !targeted ||
              !token
            ) {
              return;
            }

            finish(
              getFrameConnUserTargets()
            );
          }
        );

      window.addEventListener(
        "keydown",
        handleKeyDown,
        true
      );
    }
  );
}


/* ============================================================
   Foundry integration diagnostics
   ============================================================ */
